  errorCodes: {
    "RANGE_TOO_LARGE": {
      "status": 422,
      "meaning": "The range is longer than maxRangeDays"
    },
    "EXPORT_TOO_LARGE": {
      "status": 422,
      "meaning": "The export matched more than maxExportRows rows. Known only while the job runs (no request answers it): the job fails with this message in ExportJob.error (details.maxRows, details.matchedRows = rows read before stopping); narrow the filters and export again."
    },
    "OWNER_REQUIRED": {
      "status": 422,
      "meaning": "A metric needs a named owner before it is published"
    },
    "METRIC_IN_USE": {
      "status": 409,
      "meaning": "A published report still uses this metric"
    },
    "DATASET_UNAVAILABLE": {
      "status": 409,
      "meaning": "The dataset is not in the export registry or its owner module is disabled"
    },
    "RECIPIENT_NOT_PERMITTED": {
      "status": 422,
      "meaning": "Scheduled report recipients must be active staff holding the report's permission. details.staffIds."
    },
    "REBUILD_UNAVAILABLE": {
      "status": 409,
      "meaning": "This read model is kept from events only and cannot be rebuilt until an event log exists"
    }
  },
